#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdlib.h>

#define HASH_SIZE 131072
#define MASK (HASH_SIZE - 1)

typedef struct {
    uint64_t key;
    int count;
    int used;
} HashEntry;

HashEntry table[HASH_SIZE];

static inline uint64_t hash64(uint64_t x) {
    x ^= x >> 30;
    x *= 0xbf58476d1ce4e5b9ULL;
    x ^= x >> 27;
    x *= 0x94d049bb133111ebULL;
    x ^= x >> 31;
    return x;
}

void hash_insert(uint64_t key) {
    uint64_t idx = hash64(key) & MASK;
    while (table[idx].used) {
        if (table[idx].key == key) {
            table[idx].count++;
            return;
        }
        idx = (idx + 1) & MASK;
    }
    table[idx].used = 1;
    table[idx].key = key;
    table[idx].count = 1;
}

int hash_get(uint64_t key) {
    uint64_t idx = hash64(key) & MASK;
    while (table[idx].used) {
        if (table[idx].key == key) {
            return table[idx].count;
        }
        idx = (idx + 1) & MASK;
    }
    return 0;
}

static inline uint64_t encode_char(char c) {
    if (c >= 'a' && c <= 'z') return (uint64_t)(c - 'a' + 1);
    if (c >= '0' && c <= '9') return (uint64_t)(c - '0' + 27);
    return 0;
}

char passwords[20005][12];

int cmp_uint64(const void *a, const void *b) {
    uint64_t arg1 = *(const uint64_t *)a;
    uint64_t arg2 = *(const uint64_t *)b;
    if (arg1 < arg2) return -1;
    if (arg1 > arg2) return 1;
    return 0;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%s", passwords[i]);
        uint64_t code = 0;
        for (int j = 0; passwords[i][j]; j++) {
            code = code * 37 + encode_char(passwords[i][j]);
        }
        hash_insert(code);
    }

    long long total_pairs = 0;
    uint64_t subs[60];

    for (int i = 0; i < n; i++) {
        int len = strlen(passwords[i]);
        int sub_count = 0;
        for (int j = 0; j < len; j++) {
            uint64_t code = 0;
            for (int k = j; k < len; k++) {
                code = code * 37 + encode_char(passwords[i][k]);
                subs[sub_count++] = code;
            }
        }

        qsort(subs, sub_count, sizeof(uint64_t), cmp_uint64);

        for (int j = 0; j < sub_count; j++) {
            if (j == 0 || subs[j] != subs[j - 1]) {
                total_pairs += hash_get(subs[j]);
            }
        }
    }

    total_pairs -= n;
    printf("%lld\n", total_pairs);

    return 0;
}
