#define ALPHABET_SIZE 36

typedef struct {
    int next[ALPHABET_SIZE];
    int count;
} TrieNode;

TrieNode trie[MAX_NODES];
int trie_size = 1;

int char_to_idx(char c) {
    if (c >= 'a' && c <= 'z') return c - 'a';
    if (c >= '0' && c <= '9') return c - '0' + 26;
    return -1;
}

void insert(const char *s) {
    int u = 0;
    for (int i = 0; s[i]; i++) {
        int c = char_to_idx(s[i]);
        if (!trie[u].next[c]) {
            trie[u].next[c] = trie_size++;
        }
        u = trie[u].next[c];
    }
    trie[u].count++;
}

int query(const char *s) {
    int u = 0;
    for (int i = 0; s[i]; i++) {
        int c = char_to_idx(s[i]);
        if (!trie[u].next[c]) return 0;
        u = trie[u].next[c];
    }
    return trie[u].count;
}

int cmp_str(const void *a, const void *b) {
    return strcmp(*(const char **)a, *(const char **)b);
}

char passwords[20005][12];

