                int k = 0;
                for (int m = l; m <= r; m++) {
                    subs_buf[sub_count][k++] = passwords[i][m];
                }
                subs_buf[sub_count][k] = '\0';
                subs[sub_count] = subs_buf[sub_count];
                sub_count++;
            }
        }

        qsort(subs, sub_count, sizeof(char *), cmp_str);

        for (int j = 0; j < sub_count; j++) {
